package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderFile *os.File
var orderReader *bufio.Scanner
var currentRec OrderRec
var atEnd bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatInt(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	// handle negative not needed but keep
	av := v
	if av < 0 {
		av = -av
	}
	av = av % mod
	s := fmt.Sprintf("%0*d", width, av)
	if v < 0 {
		// COBOL would show sign, not needed
	}
	return s
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var prePic, fracPic string
	if dotIdx >= 0 {
		prePic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		prePic = pic
		fracPic = ""
	}
	fracDigits := len(fracPic)

	// integer capacity
	intCap := 0
	for _, c := range prePic {
		if c == 'Z' || c == '9' {
			intCap++
		}
	}

	// get integer and fractional parts
	absVal := val.Abs()
	// integer part truncated toward zero
	intPart := absVal.Truncate(0)
	fracPart := absVal.Sub(intPart)

	// Build integer digits string with leading zeros to intCap
	// Use decimal to get intPart exact
	intStr := intPart.StringFixed(0) // no decimal
	// intStr may be like "0" or larger
	// Remove sign
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// pad with leading zeros to at least intCap
	if len(intStr) < intCap {
		intStr = strings.Repeat("0", intCap-len(intStr)) + intStr
	} else if len(intStr) > intCap {
		// high-order digits dropped
		intStr = intStr[len(intStr)-intCap:]
	} else {
		// equal
	}
	// intStr now len == intCap

	// Build preOut
	preRunes := []rune(prePic)
	outPre := make([]rune, len(preRunes))
	digitIdx := len(intStr) - 1 // rightmost
	for i := len(preRunes) - 1; i >= 0; i-- {
		c := preRunes[i]
		if c == 'Z' || c == '9' {
			if digitIdx >= 0 {
				outPre[i] = rune(intStr[digitIdx])
				digitIdx--
			} else {
				outPre[i] = '0'
			}
		} else {
			outPre[i] = c // ',' etc
		}
	}
	// suppression pass for Z
	suppressed := true
	for i := 0; i < len(preRunes); i++ {
		if !suppressed {
			break
		}
		pc := preRunes[i]
		if pc == ',' {
			if suppressed {
				// if still suppressed, comma becomes space
				// Need to know if there is any non-zero non-suppressed ahead?
				// The classic rule: comma suppressed if all left digits suppressed.
				// Our simple loop already does that because we haven't yet exited suppression.
				outPre[i] = ' '
			}
		} else if pc == 'Z' {
			if outPre[i] == '0' {
				outPre[i] = ' '
			} else {
				suppressed = false
			}
		} else if pc == '9' {
			// 9 ends suppression, keep its digit (even if 0)
			suppressed = false
		}
	}
	preStr := string(outPre)

	if fracDigits == 0 {
		return preStr
	}
	// fractional digits
	// get fractional part as integer of fracDigits digits
	// frac = (absVal - intPart) * 10^fracDigits truncated
	// Since val already has scale 2 for these fields, truncation is fine
	shifted := fracPart.Shift(int32(fracDigits)).Truncate(0)
	fracStrRaw := shifted.StringFixed(0)
	if strings.HasPrefix(fracStrRaw, "-") {
		fracStrRaw = fracStrRaw[1:]
	}
	// pad left with zeros to fracDigits
	if len(fracStrRaw) < fracDigits {
		fracStrRaw = strings.Repeat("0", fracDigits-len(fracStrRaw)) + fracStrRaw
	} else if len(fracStrRaw) > fracDigits {
		fracStrRaw = fracStrRaw[len(fracStrRaw)-fracDigits:]
	}
	return preStr + "." + fracStrRaw
}

func parseRecord(line string) OrderRec {
	// pad to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	orId := line[0:5]
	orStat := line[5:6]
	orQtyStr := line[6:9]
	orPriceStr := line[9:15]
	var orQty int64 = 0
	trimmed := strings.TrimSpace(orQtyStr)
	if trimmed == "" {
		orQty = 0
	} else {
		// parse digits
		var v int64 = 0
		for _, ch := range orQtyStr {
			if ch >= '0' && ch <= '9' {
				v = v*10 + int64(ch-'0')
			} else if ch == ' ' {
				// ignore? treat as 0 digit? COBOL numeric field with spaces -> zero? Assume 0
			}
		}
		orQty = v
	}
	var orPrice decimal.Decimal
	// orPrice is 6 digits implied 2 decimals
	// parse digits, ignore non-digits
	digits := ""
	for _, ch := range orPriceStr {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else if ch == ' ' {
			digits += "0"
		}
	}
	if digits == "" {
		digits = "0"
	}
	// build decimal
	// digits as integer, shift -2
	// Use decimal.NewFromString
	// parse as int64
	var n int64 = 0
	for _, ch := range digits {
		n = n*10 + int64(ch-'0')
	}
	orPrice = decimal.New(n, -2)
	return OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   orQty,
		OrPrice: orPrice,
	}
}

func readPara() {
	if orderReader.Scan() {
		line := orderReader.Text()
		// LINE SEQUENTIAL: keep as is without newline, pad handled in parse
		currentRec = parseRecord(line)
	} else {
		WsEofFlag = "Y"
	}
}

func showPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(currentRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(currentRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY OR-ID " " OR-STAT " " WS-QTY-ED " " WS-PRICE-ED " " WS-TOTAL-ED
	fmt.Printf("%s %s %s %s %s\n", currentRec.OrId, currentRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func processPara() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if currentRec.OrQty == 0 {
		WsBadQty++
		fmt.Printf("%s BAD QTY\n", currentRec.OrId)
	} else if currentRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qtyDec := decimal.NewFromInt(currentRec.OrQty)
		WsTotal = qtyDec.Mul(currentRec.OrPrice)
		// truncate to 2 decimals and fit to 9(8)V99 (high order truncation)
		WsTotal = WsTotal.Truncate(2)
		// apply size: keep low-order digits that fit 8 integer digits
		// For decimal truncation of integer overflow, we need modular 10^(8) for integer part
		// Implement by shifting? But totals here small, ignore unless overflow
		// Still enforce overflow to mimic COBOL: keep low-order digits
		WsTotal = enforcePicture(WsTotal, 8, 2)
		WsNewCount++
		showPara()
	} else if currentRec.OrStat == "S" {
		qtyDec := decimal.NewFromInt(currentRec.OrQty)
		raw := qtyDec.Mul(currentRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// COBOL COMPUTE ROUNDED -> round half away from zero to scale 2
		WsTotal = raw.Round(2)
		WsTotal = enforcePicture(WsTotal, 8, 2)
		WsShipCount++
		showPara()
	} else if currentRec.OrStat == "C" {
		WsCancelCount++
		showPara()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", currentRec.OrId, currentRec.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = enforcePicture(WsGrand, 10, 2)
	readPara()
}

func enforcePicture(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep only low-order digits that fit in intDigits + scale
	// High-order digits dropped: need to do modulo 10^(intDigits) on integer part, preserve sign and scale
	if d.IsZero() {
		return d.Truncate(scale)
	}
	neg := d.Sign() < 0
	abs := d.Abs().Truncate(scale)
	// separate integer and fraction? Easier: get integer of scaled value
	// scaled = abs * 10^scale
	scaled := abs.Shift(scale).Truncate(0)
	// modulus = 10^(intDigits+scale) because scaled includes fractional digits?
	// Actually WsGrand picture 9(10)V99 => total scaled capacity = 10^12
	// intDigits=10 scale=2 => modulus = 10^(12)
	pow := decimal.NewFromInt(1)
	// compute 10^(intDigits+scale)
	exp := intDigits + int(scale)
	mod := decimal.NewFromInt(1)
	for i := 0; i < exp; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	// if scaled >= mod, keep remainder
	if scaled.Cmp(mod) >= 0 {
		// remainder = scaled % mod
		// decimal Mod not available, use Div+Truncate
		// remainder = scaled - trunc(scaled/mod)*mod
		q := scaled.Div(mod).Truncate(0)
		remainder := scaled.Sub(q.Mul(mod))
		scaled = remainder
	}
	result := scaled.Shift(-scale)
	if neg {
		result = result.Neg()
	}
	return result
}

func summaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatInt(WsNewCount, 2), formatInt(WsShipCount, 2), formatInt(WsCancelCount, 2))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatInt(WsInvalid, 2), formatInt(WsBadQty, 2))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func mainPara() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer orderFile.Close()
	orderReader = bufio.NewScanner(orderFile)
	// allow long lines
	readPara()
	for !isInputDone() {
		processPara()
	}
	orderFile.Close()
	summaryPara()
}

func main() {
	mainPara()
}

